<script>const items=<?=json_encode($items,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;let n=0;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function addRow(){const i=n++,tr=document.createElement('tr');tr.dataset.i=i;const opts=items.map(x=>`<option value="${x.id}" data-serial="${x.is_serialized}">${esc(x.nama)}</option>`).join('');tr.innerHTML=`<td class="p-3 align-top"><select name="source_types[${i}]" class="source w-full border rounded-lg px-2 py-2 text-sm"><option value="STOCK">Dari Stok</option><option value="MANUAL">Manual / Custom</option></select></td><td class="p-3 align-top"><select name="item_ids[${i}]" class="item w-full border rounded-lg px-2 py-2 text-sm"><option value="">Pilih Barang</option>${opts}</select><input name="manual_names[${i}]" class="manual hidden w-full border rounded-lg px-2 py-2 text-sm" placeholder="Nama barang custom"></td><td class="p-3 align-top"><input type="number" name="quantities[${i}]" value="1" min="1" class="w-full border rounded-lg px-2 py-2 text-center qty"></td><td class="p-3 align-top"><select name="sn_list[${i}][]" class="sn hidden w-full border rounded-lg px-2 py-2 text-sm" multiple size="4"></select><div class="nonsn text-sm italic text-gray-400">Barang non-serial.</div></td><td class="p-3 text-center align-top"><button type="button" class="text-red-500" onclick="this.closest('tr').remove()">🗑</button></td>`;document.getElementById('body').appendChild(tr);const source=tr.querySelector('.source'),item=tr.querySelector('.item'),manual=tr.querySelector('.manual'),sn=tr.querySelector('.sn'),nonsn=tr.querySelector('.nonsn');const sync=()=>{if(source.value==='MANUAL'){item.classList.add('hidden');item.removeAttribute('required');manual.classList.remove('hidden');sn.classList.add('hidden');nonsn.textContent='Barang manual tidak terkait stok.';}else{item.classList.remove('hidden');item.setAttribute('required','required');manual.classList.add('hidden');loadSn();}};const loadSn=async()=>{const o=item.options[item.selectedIndex];sn.innerHTML='';if(!o.value||o.dataset.serial!=='1'){sn.classList.add('hidden');nonsn.classList.remove('hidden');return;}const wh=document.getElementById('warehouse_id').value;if(!wh){sn.classList.add('hidden');nonsn.textContent='Pilih gudang terlebih dahulu.';return;}try{const r=await fetch(`<?=url('/api/stock')?>?warehouse_id=${wh}&item_id=${o.value}`);const d=await r.json();sn.innerHTML=(d.serials||[]).map(x=>`<option value="${esc(x.serial_number)}">${esc(x.serial_number)}</option>`).join('');sn.classList.remove('hidden');nonsn.classList.add('hidden');}catch(e){sn.classList.add('hidden');nonsn.textContent='Gagal memuat serial.';}};source.addEventListener('change',sync);item.addEventListener('change',loadSn);document.getElementById('warehouse_id').addEventListener('change',loadSn);sync();}addRow();</script>
